result:
{
  "requirements": [
    {
      "id": "REQ-001",
      "title": "View room availability",
      "text": "The system shall let a user see which meeting rooms are free for a chosen date and time range.",
      "type": "functional",
      "priority": "must",
      "acceptanceCriteria": [
        "Given a date and time range, the system lists rooms with no booking overlapping that range as free",
        "Rooms with an overlapping booking are not shown as free"
      ]
    },
    {
      "id": "REQ-002",
      "title": "Book a room",
      "text": "The system shall let a user book a free room for a chosen time slot.",
      "type": "functional",
      "priority": "must",
      "acceptanceCriteria": [
        "A user can create a booking for a free room with a start and end time",
        "The new booking appears in the room's schedule and in the user's bookings"
      ]
    },
    {
      "id": "REQ-003",
      "title": "No overlapping bookings",
      "text": "The system shall reject any booking that overlaps in time with an existing booking for the same room.",
      "type": "functional",
      "priority": "must",
      "acceptanceCriteria": [
        "A booking whose time range overlaps an existing booking for the same room is rejected with an error message",
        "Two simultaneous requests for the same room and overlapping time result in only one stored booking",
        "Bookings in different rooms at the same time are allowed"
      ]
    },
    {
      "id": "REQ-004",
      "title": "Cancel a booking",
      "text": "The system shall let a user cancel their own bookings.",
      "type": "functional",
      "priority": "must",
      "acceptanceCriteria": [
        "A user can cancel a booking they created",
        "After cancellation the time slot is shown as free",
        "A user cannot cancel another user's booking"
      ]
    },
    {
      "id": "REQ-005",
      "title": "Admin manages rooms",
      "text": "The system shall let admins add, edit and remove meeting rooms.",
      "type": "functional",
      "priority": "must",
      "acceptanceCriteria": [
        "An admin can add a room and it becomes available for booking",
        "An admin can edit a room's details",
        "An admin can remove a room",
        "Non-admin users cannot perform these actions"
      ]
    },
    {
      "id": "REQ-006",
      "title": "Browser-based",
      "text": "The system shall be usable in a web browser without installing client software.",
      "type": "non-functional",
      "priority": "must",
      "acceptanceCriteria": [
        "All user and admin functions are accessible through a web browser"
      ]
    }
  ],
  "openQuestions": [
    {
      "id": "Q-001",
      "text": "How do users sign in (e.g. company SSO, username/password, none), and how is someone designated an admin?",
      "reqIds": [
        "REQ-004",
        "REQ-005"
      ]
    },
    {
      "id": "Q-002",
      "text": "What attributes does a room have (name, capacity, location, equipment)?",
      "reqIds": [
        "REQ-005",
        "REQ-001"
      ]
    },
    {
      "id": "Q-003",
      "text": "Are there rules on time slots: fixed length or free start/end, minimum/maximum duration, bookable hours, how far ahead, and recurring bookings?",
      "reqIds": [
        "REQ-002",
        "REQ-003"
      ]
    },
    {
      "id": "Q-004",
      "text": "What should happen to existing future bookings when an admin removes a room?",
      "reqIds": [
        "REQ-005"
      ]
    },
    {
      "id": "Q-005",
      "text": "Can admins cancel or edit any user's booking, and should users be able to change a booking rather than cancel and rebook?",
      "reqIds": [
        "REQ-004"
      ]
    }
  ],
